<nav class="breadcrumbs"><a href="<?= e(url()) ?>">Ana sayfa</a><?php if(!empty($product['category_slug'])): ?> / <a href="<?= e(url('category/'.rawurlencode($product['category_slug']))) ?>"><?= e($product['category_name']) ?></a><?php endif; ?> / <?= e($product['name']) ?></nav><section class="product-detail"><div class="product-detail-image"><?php if($product['image']): ?><img src="<?= e($product['image']) ?>" alt="<?= e($product['name']) ?>"><?php else: ?><span>GAME</span><?php endif; ?></div><div class="product-detail-info"><p class="eyebrow">DİJİTAL OYUN ÜRÜNÜ</p><h1><?= e($product['name']) ?></h1><?php if(!empty($product['short_description'])): ?><p class="lead"><?= e($product['short_description']) ?></p><?php endif; ?><div class="detail-price"><?= number_format((float)$product['price'],2,',','.') ?> ₺</div><p class="delivery-note"><?= ($product['delivery_type']??'manual')==='automatic'?'Otomatik dijital teslimat':'Sipariş sonrası teslimat bilgisi' ?></p><button type="button" disabled class="coming-soon">Sepete ekleme sonraki aşamada</button></div></section><?php if(!empty($product['description'])): ?><section class="description-panel"><h2>Ürün açıklaması</h2><div><?= nl2br(e($product['description'])) ?></div></section><?php endif; ?><?php if($related): ?><section><h2>Benzer ürünler</h2><div class="products"><?php foreach($related as $p): ?><article class="product"><a class="product-link" href="<?= e(url('product/'.rawurlencode($p['slug']))) ?>"><div class="product-image"><?php if($p['image']): ?><img src="<?= e($p['image']) ?>" alt="<?= e($p['name']) ?>"><?php else: ?><span>GAME</span><?php endif; ?></div><h3><?= e($p['name']) ?></h3><p><?= e($p['short_description']) ?></p><strong><?= number_format((float)$p['price'],2,',','.') ?> ₺</strong></a></article><?php endforeach; ?></div></section><?php endif; ?>